#!/usr/bin/env node
// apply-patches.mjs (v2 -- direct file-write approach)
//
// Reproduces the 9 Phase 6b commits by writing exact final file contents
// directly via Node's raw byte APIs (Buffer, fs.writeFileSync with no
// text-mode encoding), then creating each commit with `git add -A` +
// `git commit`. Deliberately avoids `git apply`/`git am` and avoids
// reading anything as "text" at any point -- every payload below is
// base64-encoded exact bytes, decoded straight to a Buffer and written
// verbatim. This sidesteps any possible line-ending translation at any
// layer (git's own CRLF handling, MSYS2/Git-for-Windows internals, a
// sync tool watching the folder, anything) rather than trying to find
// and defeat whichever one of those is responsible.
//
// Usage: put this script in the repo root, with HEAD at 65cb77f
// ("python: add end-to-end comment wrapping gold tests"), then:
//
//   node apply-patches.mjs
//
// Requires Node.js and git on PATH. Safe to re-run after
// `git reset --hard 65cb77f` if a previous attempt left a partial state.

import { execFileSync } from 'node:child_process';
import { writeFileSync, unlinkSync, existsSync, mkdirSync, rmSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { tmpdir } from 'node:os';

// Each entry: { message: string, changes: [ {op:'write',path,content_b64} | {op:'delete',path} | {op:'rename',from,to,content_b64} ] }
const COMMITS = [{"message": "ci: add .gitattributes to lock CRLF line endings\n\nThe project's decision of record is CRLF throughout, but nothing\nmechanically enforced it — a checkout with a different\n`core.autocrlf` setting, or a contributor's global git config, could\nsilently rewrite every text file's line endings with no diff\nexplaining why.\n\nInvestigating a batch of test failures while starting Phase 6b (the\nnext two commits fix the actual bugs) traced back to exactly this\nclass of gap: line-ending handling that happened to work by\naccident wasn't protected against git itself normalizing the very\nfixtures that pin it down. `* -text` disables git's line-ending\nconversion entirely, so every file's bytes round-trip identically\nregardless of platform or local config.\n\nAdded before the two CRLF bug-fix commits, not after, so those\ncommits' own diffs are guaranteed to preserve CRLF rather than\ndepending on the committer's local git config to not mangle them.", "changes": [{"op": "write", "path": ".gitattributes", "content_b64": ""}]}, {"message": "engine: exclude CRLF artifacts from region span and rawText\n\nProbing the vendored grammar directly (same discipline as Phase 2/3 —\nsee docs/adapters.md, 'CRLF handling') found that a Python `comment`\nnode's own extent, on a CRLF-terminated line, includes the trailing\n`\\r`: the node runs to end-of-line, which sits before the `\\n` (not\npart of the node) but after the `\\r` (which is). A multi-line\ncontainer node — e.g. `concatenated_string` — reproduces the file's\nreal `\\r\\n` pairs verbatim across its own interior.\n\nTwo fixes, addressing the two places this leaked:\n\n- `normalizeRawText` collapses both shapes to a bare `\\n` in\n  `WrappableRegion.rawText`, which is display/debugging output only.\n- `trimTrailingCR` shrinks a comment-shaped node's *span* by the one\n  UTF-16/UTF-8 unit `\\r` occupies, so the span — which *is* used as\n  an editing source — never captures the file's own line-ending byte\n  as if it were region content.\n\nNeither fix touches string-literal spans: a string always terminates\nat its own closing delimiter, never at end-of-line, so the grammar\nquirk this addresses structurally cannot apply there. Surfaced by the\ntwo Phase 3 region-discovery fixtures (module docstring, implicit\nconcatenation) that happen to use CRLF source, matching this repo's\nown convention — both now pass.", "changes": [{"op": "write", "path": "packages/engine/src/discovery/discover-regions.ts", "content_b64": ""}, {"op": "write", "path": "packages/engine/src/discovery/normalize-raw-text.ts", "content_b64": ""}, {"op": "write", "path": "packages/engine/src/types/region.ts", "content_b64": ""}]}, {"message": "engine: preserve source line-ending convention in wrap output\n\nemitLineComments always joined its own output lines with a bare\n`\\n` — correct for its internal reflow/width math, which has no\nreason to think about line-ending bytes, but wrong once that text\nbecomes an actual edit against a CRLF source: the wrapped region's\ninternal newlines ended up `\\n` while the rest of the file stayed\n`\\r\\n`, producing mixed line endings and, incidentally, defeating\nthe 'already correctly wrapped' byte-identical check (the computed\nnewText could never equal a CRLF source slice).\n\n`detectLineEnding`/`applyLineEnding` (new, engine-level — every\nfuture emit function needs the same treatment, not just line\ncomments) detect a source's convention from its first line break and\nrewrite emit's bare-\\n output to match, applied once in wrapRegions\nright before a newText is compared or turned into an edit. Kept\nnarrow and documented as such: this is the minimal fix Phase 6b's\nown conformance invariant ('line endings ... preserved') needs from\nthe Python adapter today, not the general mixed-line-ending handling\nPhase 10 ('add line ending and trailing whitespace preservation')\nstill owns.\n\nAlso fixed the wrap-fixture test's own line-splitting\n(`actual.split('\\n')` → `actual.split(/\\r?\\n/)`): once\nalready-correctly-wrapped fixtures stopped generating a spurious\nfix-up edit (the point of the byte-identical check above), their\nuntouched CRLF source lines were being measured with a trailing `\\r`\nstill attached, tripping the column-limit assertion on content that\nwas never actually over limit.\n\nFull suite: 404/404 passing, typecheck and lint clean.", "changes": [{"op": "write", "path": "packages/engine/src/detect-line-ending.test.ts", "content_b64": ""}, {"op": "write", "path": "packages/engine/src/detect-line-ending.ts", "content_b64": ""}, {"op": "write", "path": "packages/engine/src/index.ts", "content_b64": ""}, {"op": "write", "path": "packages/engine/src/languages/python/wrap.ts", "content_b64": ""}, {"op": "write", "path": "packages/engine/test/wrap/python-comment-wrap-fixtures.test.ts", "content_b64": ""}]}, {"message": "engine: promote line-comment dissolve/emit to generic modules\n\ndissolveLineComments/emitLineComments (Phase 6) were already fully\ndescriptor-driven in their own signatures, but dissolveLineComments\nhad one hidden Python-only dependency: it imported\nlooksLikeCommentedOutCode directly from languages/python/, which\nhardcoded Python's own leading-keyword list (def/class/import/...).\nThat made the whole dissolve path secretly Python-only despite\nlooking generic — the Phase 6b JavaScript canary would have needed\nto fork it wholesale just to get a different keyword list.\n\nSplit the fix in two:\n\n- LanguageDescriptor.comments gains an optional codeLikeKeywords\n  pattern (data, not code — matches the project's own 'adapter is\n  data first' rule, same shape as the existing neverReflow field).\n  pythonDescriptor now declares its keyword regex there instead of\n  burying it in dissolve.\n- The generic punctuation-density heuristic moves to\n  packages/engine/src/comments/looks-like-code.ts (engine-level),\n  taking the keyword pattern as an optional parameter — a language\n  that doesn't supply one still gets the density signal alone.\n\nWith that leak closed, dissolveLineComments and emitLineComments\nthemselves have no remaining Python dependency, so both move from\nlanguages/python/ to a new generic packages/engine/src/comments/\ndirectory alongside looks-like-code.ts — this is where Phase 6b's\nnext commit (block comment support) also belongs, for the same\nreason.\n\nFound and fixed before the conformance kit or canary existed,\nexactly per Phase 6b's own stated purpose: catch this class of leak\nat the cheapest possible moment, not after Phase 7 hardens around\nit. Recorded in docs/adapters.md (added later in this series) for\nthe record.\n\nFull suite: 406/406 passing, typecheck/lint/build clean.", "changes": [{"op": "rename", "from": "packages/engine/src/languages/python/line-comment-dissolve.test.ts", "to": "packages/engine/src/comments/dissolve-line-comments.test.ts", "content_b64": ""}, {"op": "rename", "from": "packages/engine/src/languages/python/line-comment-dissolve.ts", "to": "packages/engine/src/comments/dissolve-line-comments.ts", "content_b64": ""}, {"op": "rename", "from": "packages/engine/src/languages/python/line-comment-emit.test.ts", "to": "packages/engine/src/comments/emit-line-comments.test.ts", "content_b64": ""}, {"op": "rename", "from": "packages/engine/src/languages/python/line-comment-emit.ts", "to": "packages/engine/src/comments/emit-line-comments.ts", "content_b64": ""}, {"op": "write", "path": "packages/engine/src/comments/looks-like-code.test.ts", "content_b64": ""}, {"op": "write", "path": "packages/engine/src/comments/looks-like-code.ts", "content_b64": ""}, {"op": "write", "path": "packages/engine/src/index.ts", "content_b64": ""}, {"op": "delete", "path": "packages/engine/src/languages/python/code-like-comment.test.ts"}, {"op": "delete", "path": "packages/engine/src/languages/python/code-like-comment.ts"}, {"op": "write", "path": "packages/engine/src/languages/python/descriptor.test.ts", "content_b64": ""}, {"op": "write", "path": "packages/engine/src/languages/python/descriptor.ts", "content_b64": ""}, {"op": "write", "path": "packages/engine/src/languages/python/wrap.ts", "content_b64": ""}, {"op": "write", "path": "packages/engine/src/types/adapter.ts", "content_b64": ""}]}, {"message": "engine: generalize wrapRegions into an adapter-driven entry point\n\nwrapRegions (Phase 6) hardcoded Python: it lived under\nlanguages/python/wrap.ts, validated languageId against\npythonDescriptor.id directly, and imported pythonAdapter by name.\nIts own doc comment named this generalization as exactly the\nquestion Phase 6b's canary and conformance kit exist to settle\nbefore Phase 7 hardens around a Python-only assumption — this\ncommit settles it, ahead of the canary actually needing to call it.\n\nParserManager gains adapterFor(languageId), mirroring parserFor but\nresolving the LanguageAdapter itself rather than a loaded Parser —\nboth go through the identical registry lookup a caller already\nconstructed, so wrapRegions needs no second registry parameter and\nno adapter-name import. Every remaining reference to descriptor\nfields inside wrapRegions (comment marker, comments.line) now reads\nfrom the resolved adapter's own descriptor instead of the\npythonDescriptor import.\n\nMoved from languages/python/wrap.ts to engine-level wrap.ts,\nalongside index.ts's export path and every import site (its own\ntest, and the gold-fixture wrap test under test/wrap/).\n\nRegion-kind scope is unchanged: only 'lineComment' is wrapped, every\nother kind still reports skipped with a reason. That's a\nregion-kind limitation, independent of which adapter is passed in —\nthis commit only removes the language-identity hardcoding, not the\nscope limitation, which Phase 6b's next commit (block comments) and\nlater phases narrow separately.\n\nFull suite: 409/409 passing, typecheck/lint clean.", "changes": [{"op": "write", "path": "packages/engine/src/index.ts", "content_b64": ""}, {"op": "write", "path": "packages/engine/src/parser/parser-manager.test.ts", "content_b64": ""}, {"op": "write", "path": "packages/engine/src/parser/parser-manager.ts", "content_b64": ""}, {"op": "rename", "from": "packages/engine/src/languages/python/wrap.test.ts", "to": "packages/engine/src/wrap.test.ts", "content_b64": ""}, {"op": "rename", "from": "packages/engine/src/languages/python/wrap.ts", "to": "packages/engine/src/wrap.ts", "content_b64": ""}, {"op": "write", "path": "packages/engine/test/wrap/python-comment-wrap-fixtures.test.ts", "content_b64": ""}]}, {"message": "engine: add shared adapter conformance test kit\n\nrunAdapterConformance(adapter, fixtures) is a parameterized describe\nblock every LanguageAdapter must pass — the deliverable that makes a\nnew language cheap to add (Phase 11's own framing): write a\ndescriptor plus source fixtures and call one function, rather than\ndesigning a test strategy from scratch per adapter.\n\nFixtures are source text only (ConformanceFixtures.sources), not\nhand-built engine types, matching this package's established\nfixture-driven convention. Each source runs through every wrap-based\ninvariant the plan calls out:\n\n- descriptor validates; every declared query compiles against the\n  loaded grammar\n- wrapping is idempotent (wrapping the wrapped output produces no\n  further edits — this also covers 'already-wrapped input is\n  byte-identical', since re-wrapping a first wrap's own output *is*\n  that check)\n- output re-parses with zero error nodes\n- no line exceeds the limit except a lone unbreakable atom\n- line endings, trailing whitespace, and file-final newline preserved\n\nWired up against the Python adapter now, with two fixtures — CRLF\nand LF versions of the same source — so the line-ending invariant is\nexercised both ways rather than only against whichever convention\nthis repo's own files happen to use. All 14 conformance checks pass\nagainst Python's existing Phase 6 line-comment wrapping, which is\nitself a useful signal: the CRLF fixes from the last three commits\nhold up under a test written independently of the bugs they fixed.\n\nThe JavaScript canary adapter (next commit) gets the same treatment\nonce it exists, at the hard gate this phase is really about.\n\nFull suite: 423/423 passing, typecheck/lint clean.", "changes": [{"op": "write", "path": "packages/engine/src/conformance/run-adapter-conformance.ts", "content_b64": ""}, {"op": "write", "path": "packages/engine/src/index.ts", "content_b64": ""}, {"op": "write", "path": "packages/engine/test/conformance/python-conformance.test.ts", "content_b64": ""}]}, {"message": "engine: add block comment continuation prefix support\n\nPython has no block comments, so nothing in Phase 6 exercised this\npath — flagged in the plan as the single most likely gap when\nJS/TS and C++ arrive, so it's built now, generically, driven by\ndescriptor.comments.block, the same way Phase 6b already generalized\nline-comment dissolve/emit.\n\ndissolveBlockComments/emitBlockComments (packages/engine/src/comments/)\nhandle:\n\n- Single physical line (`/* text */`) — both delimiters stripped,\n  remainder trimmed to one content line.\n- Multi-line JSDoc/Doxygen/Javadoc shape (`/**` alone on the first\n  line, ` * ` continuation-prefixed content, ` */` alone on the\n  last) — the open/close-only lines contribute no content line each,\n  so they don't register as spurious blank-paragraph breaks.\n- Plain `/* */` multi-line with no continuationPrefix at all.\n- alignContinuation: 'open' (continuation/close lines one column past\n  the region's own indent, matching `/**`'s `*`s lining up) vs\n  'indent' (flush with the region's own indent).\n\nEmit decides single-line vs. multi-line by whether the reflowed\ncontent still fits on one physical line within the column limit —\nmatching how a short block comment is conventionally written, rather\nthan always expanding to three lines regardless of length.\n\nWired into wrapRegions alongside 'lineComment': 'blockComment'\nregions are no longer reported as skipped. Restructured the\nper-region dispatch into emitWrappedLineComment/\nemitWrappedBlockComment helpers so both paths share the same\nline-ending-matching step. This matters beyond just completeness —\nwithout it, the JavaScript canary's `/** */` regions would be\nvacuously skipped by wrapRegions, and the conformance kit's\nwrap-based invariants would pass without ever actually exercising\nthis code through the real pipeline.\n\nFull suite: 439/439 passing, typecheck/lint clean.", "changes": [{"op": "write", "path": "packages/engine/src/comments/dissolve-block-comments.test.ts", "content_b64": ""}, {"op": "write", "path": "packages/engine/src/comments/dissolve-block-comments.ts", "content_b64": ""}, {"op": "write", "path": "packages/engine/src/comments/emit-block-comments.test.ts", "content_b64": ""}, {"op": "write", "path": "packages/engine/src/comments/emit-block-comments.ts", "content_b64": ""}, {"op": "write", "path": "packages/engine/src/wrap.ts", "content_b64": ""}]}, {"message": "canary: add minimal javascript adapter for comments only\n\nVendored tree-sitter-javascript.wasm the same way Phase 2 vendored\nPython's: npm pack tree-sitter-javascript@0.25.0, confirm a prebuilt\n.wasm ships at the package root (it does — same finding as Python,\nitself useful to have confirmed rather than assumed; see\ngrammars/PROVENANCE.md), copy it in, record provenance.\n\nProbed the grammar directly before writing anything against it (same\ndiscipline as Phase 2/3's Python probes):\n\n- A single comment node type covers //, plain /* */, and /** */\n  alike — no separate node per form the way one might assume.\n  javascriptAdapter's classify distinguishes them by the captured\n  node's own text, since the grammar gives no other signal.\n- Unlike Python, a // comment's span does *not* include a trailing\n  \\r on a CRLF line — this grammar's tokenizer already excludes it.\n  discoverRegions' trimTrailingCR safeguard is a no-op here, not a\n  fix this adapter needed.\n- string nodes match Python's shape exactly; template literals are a\n  separate template_string node, not captured (consistent with no\n  string support in this canary).\n\nDeliberately thin, per the plan: descriptor and one small classify\nhook, no groupRegions/isSafeToWrap/emitContext, no strings support\nbeyond the structurally-required minimum LanguageDescriptor itself\ndemands. One real scope decision, documented on classify itself: a\nplain single-star /* */ comment is excluded from discovery entirely\nrather than dissolved through the /**-configured delimiter pair it\ndoesn't match — 'skip when uncertain' over guessing.\n\nCaught one real bug before it shipped: classify's first draft only\nhandled comment nodes, silently excluding every string node from\ndiscovery (returning null for anything non-comment). Fixed to\nclassify string nodes as 'stringLiteral', matching the driver's own\nfallback and Python's adapter shape.\n\nFull suite: 452/452 passing, typecheck/lint clean. Conformance kit\ncoverage against this adapter is the next commit.", "changes": [{"op": "write", "path": "packages/engine/grammars/PROVENANCE.md", "content_b64": ""}, {"op": "write", "path": "packages/engine/grammars/tree-sitter-javascript.wasm", "content_b64": ""}, {"op": "write", "path": "packages/engine/src/index.ts", "content_b64": ""}, {"op": "write", "path": "packages/engine/src/languages/javascript/adapter.test.ts", "content_b64": ""}, {"op": "write", "path": "packages/engine/src/languages/javascript/adapter.ts", "content_b64": ""}, {"op": "write", "path": "packages/engine/src/languages/javascript/descriptor.test.ts", "content_b64": ""}, {"op": "write", "path": "packages/engine/src/languages/javascript/descriptor.ts", "content_b64": ""}]}, {"message": "canary: run conformance kit against python and javascript adapters\n\nWired runAdapterConformance up against javascriptAdapter\n(packages/engine/test/conformance/javascript-conformance.test.ts),\nmirroring the Python suite: CRLF and LF variants of one source\nexercising both // and JSDoc-style block comments, each long enough\nto actually need wrapping.\n\nAll 14 conformance checks passed against the JavaScript canary on\nthe first real run — the hard gate this phase exists for. No further\nengine change was needed at this point, because the three that were\nneeded got made ahead of time, in the commits building toward this\none (comment dissolve/emit promoted to generic modules,\ncodeLikeKeywords split into descriptor data, wrapRegions\ngeneralized) rather than discovered here and then patched in.\n\nAlong the way, generalized the conformance kit's own 'no line over\nthe limit' check: it previously only recognized the line-comment\nmarker, so it would have silently passed block-comment output\nwithout ever actually checking it (block comments didn't exist yet\nwhen that check was first written). Rewrote it to scope to\nresult.edits[*].newText directly — precise to what wrapRegions\nactually produced, rather than scanning the whole reassembled file\nand risking a false positive on an untouched original code line —\nand to strip whichever decoration a line actually carries: the line\nmarker, the block continuationPrefix, or the block open/close\ndelimiters, skipping bare delimiter-only lines entirely.\n\nAdded docs/adapters.md: the full record of every leaked assumption\nfound and fixed across this phase (commented-out-code detection\nhardcoded to Python's keywords, wrapRegions hardcoded to Python,\ndissolve/emit misplaced under languages/python/), the CRLF bugs\ncaught while establishing a clean baseline for this phase's own\nwork, the JavaScript grammar's own findings (one comment node type\nfor all three forms, no CRLF trailing-\\r quirk, template literals as\na separate node type), and the deliberate scope limits worth\ndistinguishing from oversights (plain /* */ excluded from discovery,\nno groupRegions for JS, strings structurally present but inert).\n\nAcceptance criterion met: both adapters pass the identical\nconformance suite; the JavaScript adapter's own source contains no\nimperative logic beyond the one classify hook its grammar's node\nmodel actually requires — descriptor and fixtures otherwise.\n\nFull suite: 466/466 passing, typecheck/lint/build clean.", "changes": [{"op": "write", "path": "docs/adapters.md", "content_b64": ""}, {"op": "write", "path": "packages/engine/src/comments/looks-like-code.ts", "content_b64": ""}, {"op": "write", "path": "packages/engine/src/conformance/run-adapter-conformance.ts", "content_b64": ""}, {"op": "write", "path": "packages/engine/test/conformance/javascript-conformance.test.ts", "content_b64": ""}]}];

function run(cmd, args, opts = {}) {
  return execFileSync(cmd, args, { stdio: opts.quiet ? 'pipe' : 'inherit', encoding: 'utf8' });
}

function writeBinary(path, base64) {
  mkdirSync(dirname(path), { recursive: true });
  writeFileSync(path, Buffer.from(base64, 'base64'));
}

function applyChanges(changes) {
  for (const ch of changes) {
    if (ch.op === 'write') {
      writeBinary(ch.path, ch.content_b64);
    } else if (ch.op === 'delete') {
      if (existsSync(ch.path)) rmSync(ch.path);
    } else if (ch.op === 'rename') {
      if (existsSync(ch.from)) rmSync(ch.from);
      writeBinary(ch.to, ch.content_b64);
    } else {
      throw new Error(`unknown op: ${ch.op}`);
    }
  }
}

function main() {
  const status = run('git', ['status', '--porcelain', '--untracked-files=no'], { quiet: true });
  if (status.trim().length > 0) {
    console.error('Working tree has uncommitted tracked changes. Commit, stash, or `git reset --hard 65cb77f` first.');
    process.exit(1);
  }

  for (let i = 0; i < COMMITS.length; i++) {
    const { message, changes } = COMMITS[i];
    const subject = message.split('\n')[0];
    console.log(`\n--- [${i + 1}/${COMMITS.length}] ${subject} ---`);

    applyChanges(changes);

    // Written OUTSIDE the repo (OS temp dir), not inside it -- `git add -A`
    // runs before this file is cleaned up, and a temp file sitting inside
    // the working tree at that moment would get swept up and committed
    // right along with everything else (this bit an earlier version of
    // this script on its very last commit).
    const msgFile = join(tmpdir(), `rewrap-plus-commit-msg-${i}.tmp`);
    writeFileSync(msgFile, message, 'utf8');
    try {
      run('git', ['add', '-A']);
      run('git', ['commit', '-F', msgFile]);
    } finally {
      if (existsSync(msgFile)) unlinkSync(msgFile);
    }
  }

  console.log(`\nDone. ${COMMITS.length} commits applied.`);
  run('git', ['log', '--oneline', `-${COMMITS.length}`]);
}

main();
